void go(List<Integer> path) {
    if (path.size() == 2) {
        System.out.println(path);
        return;
    }
    for (int x = 1; x <= 2; x++) {
        path.add(x);
        go(path);
        path.___(path.size() - 1);
    }
}

function go(path) {
  if (path.length === 2) {
    console.log(path.join(' '));
    return;
  }
  for (const x of [1, 2]) {
    path.push(x);
    go(path);
    path.___();
  }
}

void go(vector<int>& path) {
    if (path.size() == 2) {
        printf("%d %d\n", path[0], path[1]);
        return;
    }
    for (int x = 1; x <= 2; x++) {
        path.push_back(x);
        go(path);
        path.___();
    }
}

def go(depth, s):
    if s > 3:
        return 0
    if depth == 2:
        return 1
    return sum(go(depth + 1, s + x)
               for x in (1, 2, 3))

int go(int depth, int s) {
    if (s > 3) return 0;
    if (depth == 2) return 1;
    int cnt = 0;
    for (int x = 1; x <= 3; x++)
        cnt += go(depth + 1, s + x);
    return cnt;
}

function go(depth, s) {
  if (s > 3) return 0;
  if (depth === 2) return 1;
  let cnt = 0;
  for (let x = 1; x <= 3; x++) {
    cnt += go(depth + 1, s + x);
  }
  return cnt;
}

int go(int depth, int s) {
    if (s > 3) return 0;
    if (depth == 2) return 1;
    int cnt = 0;
    for (int x = 1; x <= 3; x++)
        cnt += go(depth + 1, s + x);
    return cnt;
}
